// Old style — completion handlers
func loadUser(id: String, completion: @escaping (Result<User, Error>) -> Void) { /* ... */ }

// New style — async/await
func loadUser(id: String) async throws -> User {
  let url = URL(string: "https://api.example.com/users/\(id)")!
  let (data, _) = try await URLSession.shared.data(from: url)
  return try JSONDecoder().decode(User.self, from: data)
}

// Sequencing — reads like synchronous code
func loadProfile() async throws -> Profile {
  let user = try await loadUser(id: "42")
  let posts = try await loadPosts(for: user.id)
  let avatar = try await loadAvatar(for: user.id)
  return Profile(user: user, posts: posts, avatar: avatar)
}

// Calling async from a sync context.
// A Task inherits the isolation of the context that created it, so inside a
// @MainActor type there is no need to hop back with MainActor.run.
@MainActor
final class ProfileViewModel {
  func onAppear() {
    Task {
      do    { show(try await loadProfile()) }   // resumes on the main actor
      catch { showError(error) }
    }
  }
  func show(_ p: Profile) {}
  func showError(_ e: Error) {}
}

// Bridge a legacy callback API into async
func loadUserBridged(id: String) async throws -> User {
  try await withCheckedThrowingContinuation { cont in
    legacy.loadUser(id: id) { result in cont.resume(with: result) }  // exactly once
  }
}

// Concurrent with async let
func loadDashboard() async throws -> Dashboard {
  async let posts = api.posts()
  async let friends = api.friends()
  async let news = api.news()
  // Three requests fly in parallel; the await collects all three (all-or-throw)
  return try await Dashboard(posts: posts, friends: friends, news: news)
}

// Dynamic fan-out via TaskGroup
func loadAvatars(_ ids: [String]) async throws -> [String: UIImage] {
  try await withThrowingTaskGroup(of: (String, UIImage).self) { group in
    for id in ids {
      group.addTask { (id, try await api.avatar(id: id)) }
    }
    var result: [String: UIImage] = [:]
    for try await (id, image) in group {
      result[id] = image
    }
    return result
  }
}

// Cancellation propagation
func search(_ q: String) async throws -> [SearchHit] {
  try Task.checkCancellation()   // throws CancellationError if the parent died
  return try await api.search(q)
}

// Managing an unstructured Task as state
@MainActor
@Observable
final class SearchModel {
  var results: [SearchHit] = []
  private var task: Task<Void, Never>?

  func search(_ q: String) {
    task?.cancel()               // the previous keystroke's work is now garbage
    task = Task {                // inherits @MainActor from self
      guard let r = try? await api.search(q), !Task.isCancelled else { return }
      results = r                // already on the main actor
    }
  }
}

actor Counter {
  private var value: Int = 0
  func increment() { value += 1 }
  func current() -> Int { value }
  nonisolated let id = UUID()                  // immutable — no isolation needed
  nonisolated func describe() -> String { "Counter(\(id))" }
}

let c = Counter()
Task { await c.increment() }
Task { print(await c.current()) }
// No locks, no DispatchQueue — the compiler enforces serial access.

// MainActor — pin the whole type instead of hopping at each call site
@MainActor
@Observable
final class HomeModel {
  var items: [Item] = []
  func reload() async {
    let next = try? await api.items()   // suspends; runs off the main actor
    items = next ?? []                  // resumes back on the main actor
  }
}

// Reentrancy gotcha — the classic duplicate-request bug
actor ImageCache {
  private var cached: [URL: UIImage] = [:]
  private var inFlight: [URL: Task<UIImage, Error>] = [:]

  func image(at url: URL) async throws -> UIImage {
    if let hit = cached[url] { return hit }
    // ❌ Without the inFlight map, ten concurrent callers all miss the cache
    //    here and all start their own download: the actor is reentrant, so
    //    each one gets to run before any of them finishes.
    if let running = inFlight[url] { return try await running.value }

    let task = Task { try await download(url) }
    inFlight[url] = task
    defer { inFlight[url] = nil }
    let image = try await task.value
    cached[url] = image
    return image
  }
}

// Consume any AsyncSequence
for try await line in url.lines {                   // URL.AsyncBytes
  print(line)
}

for await note in NotificationCenter.default.notifications(named: .myEvent) {
  handle(note)
}

// Bridge a delegate API — makeStream hands back stream + continuation together
final class LocationFeed: NSObject, CLLocationManagerDelegate {
  let stream: AsyncStream<CLLocation>
  private let continuation: AsyncStream<CLLocation>.Continuation
  private let manager = CLLocationManager()

  override init() {
    (stream, continuation) = AsyncStream.makeStream(
      of: CLLocation.self,
      bufferingPolicy: .bufferingNewest(1)   // never queue stale fixes
    )
    super.init()
    manager.delegate = self
    continuation.onTermination = { [manager] _ in manager.stopUpdatingLocation() }
    manager.startUpdatingLocation()
  }

  func locationManager(_ m: CLLocationManager, didUpdateLocations locs: [CLLocation]) {
    for l in locs { continuation.yield(l) }
  }

  deinit { continuation.finish() }             // otherwise `for await` hangs
}

// Consumer — cancelling the Task tears the stream down via onTermination
let feed = LocationFeed()
let task = Task {
  for await loc in feed.stream { update(loc) }
}

